import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';

export class BookStore {
  constructor(filePath) {
    this.filePath = filePath;
    this.books = [];
    this.loaded = false;
  }

  async load() {
    try {
      const raw = await readFile(this.filePath, 'utf8');
      const parsed = JSON.parse(raw);
      this.books = Array.isArray(parsed) ? parsed : [];
    } catch (err) {
      if (err.code !== 'ENOENT') throw err;
      this.books = [];
    }
    this.loaded = true;
    return this;
  }

  async save() {
    await mkdir(dirname(this.filePath), { recursive: true });
    // Write to a temp file and rename so a crash mid-write can't truncate the real file.
    const tmp = `${this.filePath}.tmp`;
    await writeFile(tmp, JSON.stringify(this.books, null, 2) + '\n');
    await rename(tmp, this.filePath);
  }

  all() {
    return [...this.books];
  }

  reading() {
    return this.books.filter((b) => !b.finishedAt);
  }

  finished() {
    return this.books
      .filter((b) => b.finishedAt)
      .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));
  }

  get(id) {
    return this.books.find((b) => b.id === id) ?? null;
  }

  async add({ title, author, notes = '' }) {
    title = (title ?? '').trim();
    author = (author ?? '').trim();
    notes = (notes ?? '').trim();
    if (!title) throw new ValidationError('Title is required.');
    if (!author) throw new ValidationError('Author is required.');
    const book = {
      id: randomUUID(),
      title,
      author,
      notes,
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    this.books.push(book);
    await this.save();
    return book;
  }

  async finish(id) {
    const book = this.get(id);
    if (!book) return null;
    if (!book.finishedAt) {
      book.finishedAt = new Date().toISOString();
      await this.save();
    }
    return book;
  }
}

export class ValidationError extends Error {}

