import { createServer } from 'node:http';
import { BookStore, ValidationError } from './store.js';
import { bookPage, homePage, notFoundPage } from './html.js';

const MAX_BODY = 64 * 1024;

function readForm(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY) {
        reject(Object.assign(new Error('Request body too large'), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      const params = new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
      resolve(Object.fromEntries(params));
    });
    req.on('error', reject);
  });
}

function send(res, status, html) {
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Length': Buffer.byteLength(html),
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function shareUrlFor(req, book, publicUrl) {
  const base = publicUrl ?? `http://${req.headers.host ?? 'localhost'}`;
  return new URL(`/books/${book.id}`, base).toString();
}

export function createApp(store, { publicUrl } = {}) {
  return async function handle(req, res) {
    const url = new URL(req.url, 'http://localhost');
    const { method } = req;
    const path = url.pathname;

    if (method === 'GET' && path === '/') {
      return send(res, 200, homePage({ reading: store.reading(), finished: store.finished() }));
    }

    if (method === 'POST' && path === '/books') {
      const form = await readForm(req);
      try {
        const book = await store.add(form);
        return redirect(res, `/books/${book.id}`);
      } catch (err) {
        if (!(err instanceof ValidationError)) throw err;
        const page = homePage({
          reading: store.reading(),
          finished: store.finished(),
          error: err.message,
          values: form,
        });
        return send(res, 400, page);
      }
    }

    const bookMatch = path.match(/^\/books\/([0-9a-f-]+)(\/finish)?$/);
    if (bookMatch) {
      const [, id, finish] = bookMatch;
      if (method === 'GET' && !finish) {
        const book = store.get(id);
        if (!book) return send(res, 404, notFoundPage());
        return send(res, 200, bookPage(book, shareUrlFor(req, book, publicUrl)));
      }
      if (method === 'POST' && finish) {
        const book = await store.finish(id);
        if (!book) return send(res, 404, notFoundPage());
        const back = req.headers.referer?.endsWith(`/books/${id}`) ? `/books/${id}` : '/';
        return redirect(res, back);
      }
    }

    return send(res, 404, notFoundPage());
  };
}

export async function startServer({ port, dataFile, publicUrl }) {
  const store = await new BookStore(dataFile).load();
  const handle = createApp(store, { publicUrl });
  const server = createServer((req, res) => {
    handle(req, res).catch((err) => {
      const status = err.status ?? 500;
      if (status >= 500) console.error(err);
      if (!res.headersSent) send(res, status, `<h1>${status === 413 ? 'Request too large' : 'Something went wrong'}</h1>`);
      else res.end();
    });
  });
  await new Promise((resolve) => server.listen(port, resolve));
  return { server, store, port: server.address().port };
}

