import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { BookStore, ValidationError } from '../src/store.js';

let dir;
let file;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  file = join(dir, 'nested', 'books.json');
});

afterEach(() => rm(dir, { recursive: true, force: true }));

describe('BookStore', () => {
  it('starts empty when the file does not exist', async () => {
    const store = await new BookStore(file).load();
    expect(store.all()).toEqual([]);
  });

  it('adds a book and persists it to the JSON file', async () => {
    const store = await new BookStore(file).load();
    const book = await store.add({ title: ' Dune ', author: 'Frank Herbert', notes: 'Spice.' });

    expect(book).toMatchObject({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.', finishedAt: null });
    expect(book.id).toMatch(/^[0-9a-f-]{36}$/);

    const onDisk = JSON.parse(await readFile(file, 'utf8'));
    expect(onDisk).toEqual([book]);
  });

  it('reloads books from disk', async () => {
    const first = await new BookStore(file).load();
    await first.add({ title: 'A', author: 'B' });

    const second = await new BookStore(file).load();
    expect(second.all()).toHaveLength(1);
    expect(second.all()[0].title).toBe('A');
  });

  it('rejects missing title or author', async () => {
    const store = await new BookStore(file).load();
    await expect(store.add({ title: '', author: 'X' })).rejects.toBeInstanceOf(ValidationError);
    await expect(store.add({ title: 'X', author: '   ' })).rejects.toBeInstanceOf(ValidationError);
    expect(store.all()).toEqual([]);
  });

  it('splits books into reading and finished', async () => {
    const store = await new BookStore(file).load();
    const a = await store.add({ title: 'A', author: 'x' });
    const b = await store.add({ title: 'B', author: 'x' });

    await store.finish(a.id);

    expect(store.reading().map((x) => x.id)).toEqual([b.id]);
    expect(store.finished().map((x) => x.id)).toEqual([a.id]);
    expect(store.get(a.id).finishedAt).toBeTruthy();
  });

  it('finish is idempotent and returns null for unknown ids', async () => {
    const store = await new BookStore(file).load();
    const a = await store.add({ title: 'A', author: 'x' });
    const first = (await store.finish(a.id)).finishedAt;
    const second = (await store.finish(a.id)).finishedAt;
    expect(second).toBe(first);
    expect(await store.finish('nope')).toBeNull();
  });
});

